"""Build every public page. Python standard library only; run after editing content."""
import json, html, re
from business import DETAILS, ANALYTICS_CONSENT
from pathlib import Path
R=Path(__file__).parent
OUT=R/'public'
data=json.loads((R/'content.json').read_text(encoding='utf-8'))
cases=json.loads((R/'cases.json').read_text(encoding='utf-8'))
bycase={c['slug']:c for c in cases}
solutions=sorted(data['solutions'],key=lambda x:['krovlya','vhodnye-gruppy','teplye-poly','truby','ploshchadki'].index(x['slug']))
services=data['services']
pages=[]
esc=lambda s:html.escape(str(s),quote=True)
def icon(n):
 paths={'pin':'<circle cx="12" cy="9" r="2.5"/><path d="M19 9c0 6-7 12-7 12S5 15 5 9a7 7 0 0 1 14 0Z"/>','talk':'<path d="M4 4h16v12H9l-5 4V4Z"/><path d="M8 8h8M8 12h5"/>','plan':'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 7h6M9 11h6M9 15h3"/>','check':'<path d="m5 12 4 4L19 6"/><circle cx="12" cy="12" r="10"/>','cable':'<path d="M19 4H7a4 4 0 0 0 0 8h10a4 4 0 0 1 0 8H5"/>','file':'<path d="M5 3h9l5 5v13H5V3Zm9 0v6h5M8 13h8M8 17h5"/>'}
 return f'<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">{paths.get(n,paths["cable"])}</svg>'
def photo(slug,n=0,cls='',eager=False):
 p=bycase[slug]['photos'][n]
 return f'<img class="{cls}" src="{p["src"]}" srcset="{p["small"]} 640w, {p["src"]} 1280w" sizes="(max-width: 700px) 100vw, 55vw" width="{p["width"]}" height="{p["height"]}" alt="{esc(bycase[slug]["title"])} — фото монтажа {n+1}" loading="{"eager" if eager else "lazy"}" {"fetchpriority=high" if eager else ""}>'
def btn(text='Получить консультацию',url='#request',secondary=False):
 return f'<a class="button {"secondary" if secondary else ""}" href="{url}">{text}</a>'
def heading(title,description='',kicker=''):
 return f'<div class="section-heading"><div>{f"<p class=eyebrow>{kicker}</p>" if kicker else ""}<h2>{title}</h2>{f"<p>{description}</p>" if description else ""}</div></div>'
def roadmap():
 return '<div class="roadmap wrap">'+''.join(f'<div><span class="step-number">0{i+1}</span><div><h3>{h}</h3><p>{t}</p></div></div>' for i,(h,t) in enumerate([('Консультация','Обсуждаем задачу и особенности вашего объекта.'),('Решение','Подбираем оборудование и схему обогрева.'),('Расчёт','Готовим предложение по согласованному объёму.')]))+'</div>'
def form(topic='Ваш объект'):
 return f'''<section class="wrap request-section" id="request"><div class="request-layout"><div class="request-copy"><p class="eyebrow">Начнём с разговора</p><h2>Обсудим ваш объект</h2><p>Оставьте контакт и коротко опишите задачу. Менеджер уточнит детали и поможет определить следующий шаг.</p><ul class="benefits"><li>{icon('talk')}<span><strong>Консультация — бесплатно</strong>Обсудим, где и какой обогрев нужен.</span></li><li>{icon('plan')}<span><strong>Решение под ваш объект</strong>Подготовим подбор и расчёт после уточнения данных.</span></li><li>{icon('file')}<span><strong>Есть фото или проект?</strong>Приложите к заявке — так разговор будет предметнее.</span></li></ul><p class="fine">Проектная и исполнительная документация, диагностика и условия выезда согласуются отдельно.</p></div><form class="lead-form" data-topic="{esc(topic)}"><label for="contact">Телефон или email <span aria-hidden="true">*</span></label><input id="contact" name="contact" autocomplete="email" required maxlength="150" placeholder="Как с вами связаться"><label for="message">Коротко о задаче</label><textarea id="message" name="message" maxlength="4000" rows="3" placeholder="Что нужно обогреть или проверить?"></textarea><details class="more-fields"><summary>Добавить имя, город или материалы</summary><div class="field-pair"><label>Ваше имя<input name="name" autocomplete="name" maxlength="100"></label><label>Город объекта<input name="city" autocomplete="address-level2" maxlength="100"></label></div><label class="upload">Фото или ТЗ<input type="file" name="files" multiple accept=".jpg,.jpeg,.png,.webp,.pdf,.docx,.xlsx,.dwg"><small>До 3 файлов, суммарно до 10 МБ. Фото, PDF, DOCX, XLSX или DWG.</small></label></details><div class="trap" aria-hidden="true"><label>Ваш сайт<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="consent"><input type="checkbox" name="consent" required><span>Даю <a href="/consent/" target="_blank" rel="noopener">согласие на обработку персональных данных</a> и ознакомлен с <a href="/privacy/" target="_blank" rel="noopener">политикой</a>.</span></label><button class="button" type="submit">Передать задачу менеджеру</button><p class="form-status" role="status" tabindex="-1"></p><p class="form-direct">Или свяжитесь напрямую:<br><a href="tel:+79301755000">+7 930 175 50 00</a> · <a href="mailto:obogrevsistem@yandex.ru">obogrevsistem@yandex.ru</a></p><noscript><p>Для формы включите JavaScript или отправьте письмо на указанный email.</p></noscript></form></div></section>'''
def project_cards(slugs=None):
 cs=[bycase[s] for s in slugs] if slugs else cases
 return '<div class="project-grid">'+''.join(f'<article class="project-card" data-category="{c["category"]}"><a href="/proekty/{c["slug"]}/">{photo(c["slug"])}<div class="project-caption"><span class="eyebrow">{dict(roof="Кровля и водостоки",entrance="Входные зоны",floor="Тёплые полы",control="Управление")[c["category"]]}</span><h3>{c["title"]}</h3><p>Посмотреть детали монтажа</p></div></a></article>' for c in cs)+'</div>'
def faq(items):
 return '<div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'
def textblocks(items):
 return '<div class="text-grid">'+''.join(f'<article><span class="block-number">0{i+1}</span><h3>{h}</h3><p>{t}</p></article>' for i,(h,t) in enumerate(items))+'</div>'
def solution_cards():
 imgs=['krovlya-i-okna','vhodnaya-gruppa','teplyy-pol']
 return '<div class="solutions-grid">'+''.join(f'<a class="solution-card solution-{i}" href="/resheniya/{s["slug"]}/">{photo(imgs[i])}<div><h3>{s["short"]}</h3><p>{["Путь талой воды: от кромки кровли до водостока.","Обогрев ступеней, пандусов и площадок перед входом.","Кабель и нагревательные маты для ваших помещений."][i]}</p><span class="card-link">Подробнее о решении</span></div></a>' for i,s in enumerate(solutions[:3]))+'</div><div class="other-solutions"><span>Другие задачи:</span><a href="/resheniya/truby/">Трубы и трубопроводы</a><a href="/resheniya/ploshchadki/">Площадки и дорожки</a></div>'
def hero(title,desc,slug=None,eyebrow='Системы кабельного обогрева',home=False):
 title=title.replace('<br>','<br> ')
 return f'''<section class="hero {"home-hero" if home else "inner-hero"} {"text-hero" if not slug else ""}"><div class="hero-content"><div class="hero-copy"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="hero-description">{desc}</p><div class="geography">{icon('pin')}<span><strong>Бригада в Твери</strong>Выезды — по договорённости.</span></div><div class="hero-actions">{btn()}{btn('Передать проект или ТЗ','/klientam/organizaciyam/#request',True)}</div></div>{f'<figure class="hero-image">{photo(slug,eager=True)}<figcaption>На фото — наша работа · <a href="/proekty/{slug}/">детали монтажа</a></figcaption></figure>' if slug else ''}</div></section>'''
def breadcrumb(title,parent=None):
 return '<nav class="breadcrumbs wrap" aria-label="Хлебные крошки"><a href="/">Главная</a><span>/</span>'+ (f'<a href="{parent[1]}">{parent[0]}</a><span>/</span>' if parent else '')+f'<span aria-current="page">{title}</span></nav>'
def layout(path,title,desc,body,parent=None,lead=True):
 if path=='/kontakty/':body=body.replace('<h2>','<h1>',1).replace('</h2>','</h1>',1)
 nav=[('/resheniya/','Решения'),('/uslugi/','Услуги'),('/proekty/','Проекты'),('/o-kompanii/','О компании'),('/kontakty/','Контакты')]
 links=''.join(f'<a href="{p}" {"aria-current=page" if path.startswith(p) else ""}>{t}</a>' for p,t in nav)
 doc=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} — ОбогревСистем</title><meta name="description" content="{esc(desc)}"><meta name="robots" content="@@ROBOTS@@"><link rel="canonical" href="@@SITE_URL@@{path}"><link rel="icon" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script></head><body><a class="skip" href="#main">К содержанию</a><header class="header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="ОбогревСистем — на главную"><img src="/assets/logo.svg" width="686" height="124" alt="ОбогревСистем. Системы кабельного обогрева"></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Меню <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Основное меню">{links}<a class="nav-mobile-contact" href="tel:+79301755000">+7 930 175 50 00</a></nav><a class="header-phone" href="tel:+79301755000">+7 930 175 50 00</a>{btn('Связаться','#request' if lead else '/kontakty/')}</div></header><main id="main">{breadcrumb(title,parent) if path!='/' else ''}{body}{form(title) if lead else ''}</main><footer class="footer"><div class="wrap"><div class="footer-grid"><div><a href="/"><img class="footer-logo" src="/assets/logo.svg" width="686" height="124" alt="ОбогревСистем"></a><p>Кабельный обогрев.<br>От задачи — к решению.</p><p class="fine">Бригада в Твери.<br>Выезды — по договорённости.</p></div><div><h3>Направления</h3>{links}<a href="/garantiya/">Гарантия и обращения</a></div><div><h3>Заказчикам</h3><a href="/klientam/organizaciyam/">Организациям</a><a href="/klientam/tendery/">Тендеры и контракты</a><a href="/klientam/chastnym/">Частным клиентам</a></div><div class="footer-contacts"><h3>Обсудим ваш объект</h3><a class="contact-phone" href="tel:+79301755000">+7 930 175 50 00</a><a href="mailto:obogrevsistem@yandex.ru">obogrevsistem@yandex.ru</a><p class="fine">Фото, проект и описание задачи можно отправить на почту.</p></div></div><p class="fine">ИП Кривенко Андрей Николаевич · ИНН 695203276494 · ОГРНИП 324690000059805<br><a href="/kontakty/#requisites">Реквизиты и официальные обращения</a></p><div class="footer-bottom"><span>© <span data-year>2026</span> ОбогревСистем</span><a href="/privacy/">Политика обработки данных</a><a href="/consent/">Согласие на обработку</a><button class="link-button" data-cookie-settings hidden>Настройки аналитики</button></div></div></footer><div class="mobile-contact"><a href="tel:+79301755000">Позвонить</a><a href="{'#request' if lead else '/kontakty/'}">Обсудить объект</a></div><div class="cookie-panel" hidden><p>Аналитика помогает понять, какие разделы полезны. Разрешить Яндекс Метрику? <a href="/privacy/">Подробнее</a></p><div><button class="button" data-cookie="yes">Разрешить</button><button class="button secondary" data-cookie="no">Без аналитики</button></div></div><dialog class="lightbox" aria-label="Фотография работы"><button class="lightbox-close" aria-label="Закрыть фотографию">Закрыть ×</button><img alt=""><p></p></dialog></body></html>'''
 target=OUT/(path.strip('/')+'/index.html' if path!='/' else 'index.html')
 target.parent.mkdir(parents=True,exist_ok=True);target.write_text(doc,encoding='utf-8');pages.append({'path':path,'title':title})

home=hero('Обогрев кровли<br>и водостоков','Бесплатная консультация, техническое решение и расчёт по вашему объекту.','myagkaya-krovlya',home=True)+roadmap()
home+=f'<section class="wrap section">{heading("Решения для вашего объекта","Подбираем систему под конструкцию и условия эксплуатации. Можно обсудить весь комплекс работ или только поставку оборудования.")}{solution_cards()}</section>'
