home+=f'<section class="wrap section">{heading("От задачи — к рабочей системе","Для производственных и общественных зданий, управляющих организаций и частных объектов.","Подход к работе")}{textblocks([("Новая система","Изучим объект, предложим зоны обогрева и комплектацию. Состав монтажа и документации согласуем до начала работ."),("Есть проект или ТЗ","Рассмотрим документацию и нужный объём: поставку, монтаж или оба этапа. Уточним условия доступа и подключения."),("Обогрев уже установлен","Если система не включается или работает частично, начнём с обсуждения симптомов и условий диагностики.")])}<div class="section-actions">{btn("Услуги и этапы работы","/uslugi/",True)}{btn("Для организаций","/klientam/organizaciyam/",True)}</div></section>'
layout('/','Обогрев кровли и водостоков в Твери','Обогрев кровли, входных зон и полов. Консультация, подбор и расчёт. Бригада в Твери, выезды по договорённости.',home)

layout('/resheniya/','Решения для кабельного обогрева','Выберите объект: кровля, ступени, полы, трубы или открытые площадки.',hero('Где нужен обогрев','Сначала определяем задачу и особенности объекта. Затем подбираем систему, управление и необходимый состав работ.')+f'<section class="wrap section">{solution_cards()}</section>'+f'<section class="wrap section compact">{heading("С чего начать","Достаточно описания проблемы. Чертежи и размеры помогут уточнить решение, но не обязательны для первого разговора.")}{textblocks([("Объект","Что нужно обогреть, где находится объект и на какой стадии строительство."),("Условия","Конструкция, покрытие, доступ к питанию и ограничения эксплуатации."),("Формат работы","Система с монтажом, отдельное оборудование или помощь с существующим обогревом.")])}</section>')

