 if s['slug'] in solution_projects:b+=f'<section class="section soft"><div class="wrap">{heading("Посмотрите на монтаж","Фотографии наших работ: размещение нагревательных элементов и детали установки.")}{project_cards(solution_projects[s["slug"]])}</div></section>'
 else:b+=f'<section class="section soft"><div class="wrap">{heading("Система работает как единое целое","При подборе рассматриваем не только кабель, но и защиту, управление, соединения и условия установки.")}{textblocks([("Нагревательные элементы","Тип и параметры зависят от задачи и конструкции объекта."),("Управление","Обсудим режим работы, датчики и доступную электрическую мощность."),("Монтаж и проверка","Согласуем крепления, подключение и объём проверок перед эксплуатацией.")])}</div></section>'
 parts=re.split(r'(?<=\?)\s*',s['faq']);pairs=[]
