service_intro+='<section class="wrap section"><div class="service-list">'+''.join(f'<a href="/uslugi/{s["slug"]}/"><span class="block-number">0{i+1}</span><div><h2>{s["short"]}</h2><p>{s["intro"]}</p></div><span class="text-link">Подробнее</span></a>' for i,s in enumerate(services))+'</div></section>'
